// Vendors MapLibre GL JS (the vector-map engine) and its Leaflet plugin into a plain JS module, so the crew
// app's offline map page can embed them inline — no CDN, works with zero connectivity. Same idea as
// build-leaflet-bundle.mjs. Run after `npm install`, and again whenever these two packages are upgraded:
//
//   npm run build:maplibre
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const read = (p) => readFileSync(p, 'utf8');

const mlDir = dirname(require.resolve('maplibre-gl/package.json'));
const { version: mlVersion } = JSON.parse(read(join(mlDir, 'package.json')));
const plugDir = dirname(require.resolve('@maplibre/maplibre-gl-leaflet/package.json'));
const { version: plugVersion } = JSON.parse(read(join(plugDir, 'package.json')));

// The files are inlined into <script>/<style>, so neutralise any closing tag.
const js = (s) => s.replace(/<\/script/gi, '<\\/script');
const css = (s) => s.replace(/<\/style/gi, '<\\/style');

const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'lib', 'offlineMap', 'maplibreBundle.js');
writeFileSync(
  out,
  `// GENERATED by scripts/build-maplibre-bundle.mjs — do not edit by hand.
// MapLibre GL JS ${mlVersion} (BSD-3-Clause) and @maplibre/maplibre-gl-leaflet ${plugVersion} (ISC), vendored for offline use.
export const MAPLIBRE_VERSION = ${JSON.stringify(mlVersion)};
export const MAPLIBRE_CSS = ${JSON.stringify(css(read(join(mlDir, 'dist', 'maplibre-gl.css'))))};
export const MAPLIBRE_JS = ${JSON.stringify(js(read(join(mlDir, 'dist', 'maplibre-gl.js'))))};
export const MAPLIBRE_LEAFLET_JS = ${JSON.stringify(js(read(join(plugDir, 'leaflet-maplibre-gl.js'))))};
`
);
console.log(`Wrote MapLibre ${mlVersion} + leaflet plugin ${plugVersion} bundle -> ${out}`);
